  '    vec4 s = marchDeck(d, uScud, 2.0, uWind * 1.7, uSteps * 0.4, jit, tm);',
  '    float f = 1.0 - exp(-tm / uFog.x); vec3 sl = s.rgb * (1.0 - f) + fogC * (1.0 - s.a) * f;',
  '    L = sl + L * s.a; T *= s.a; }',
