  rurubitaki: function (E, t, out) { var p = snR(E, 0.95, 1.05); return snPhrase(E, t, out, [{ t: 0, d: 0.12, f: [3000 * p, 3400 * p], a: 0.6 }, { t: 0.16, d: 0.1, f: [4200 * p, 3800 * p], a: 0.7 }, { t: 0.3, d: 0.08, f: [3600 * p, 3900 * p], a: 0.6 }, { t: 0.42, d: 0.2, f: [3300 * p, 3000 * p], a: 0.7 }], { harm: [[1, 1], [2, 0.1]] }); },
