    for (i = 0; i < reps; i++) { n.push({ t: b, d: 0.07, f: [4000 * p, 3950 * p], a: 0.8 }, { t: b + 0.12, d: 0.05, f: [3900 * p], a: 0.6 }, { t: b + 0.19, d: 0.05, f: [3900 * p], a: 0.6 }, { t: b + 0.27, d: 0.16, f: [4100 * p, 4000 * p], a: 0.75 }); b += snR(E, 0.9, 1.4); }
