  if (lightForDate(d) !== L) { var H = { morning: 6.5, day: 11.5, dusk: 17.6, night: 21.5 }[L] || 11.5; d = new Date(d.getFullYear(), d.getMonth(), d.getDate(), Math.floor(H), Math.round((H % 1) * 60)); }
  return d;
